extends SceneTree
const Session = preload("res://simulation/match_session.gd")
const REPORT_PATH: String = "C:/Users/m/Documents/Relic Arena MY/Guia_Godot4/revisoes/animacoes_2026-10-13/boss_readonly_repro.json"
var passed: int = 0
var failed: int = 0
var cases: Array[Dictionary] = []
var checks: Array[Dictionary] = []

func _initialize() -> void:
    _case_timeout()
    _case_boss_defeat()
    var report: Dictionary = {"scope": "Disposable real Session/core fixtures; no gameplay files changed", "cases": cases, "checks": checks, "passed": passed, "failed": failed, "expected_exit_code": 1 if failed > 0 else 0}
    var file: FileAccess = FileAccess.open(REPORT_PATH, FileAccess.WRITE)
    if file == null:
        printerr("Cannot write audit report")
        quit(2)
        return
    file.store_string(JSON.stringify(report, "\t") + "\n")
    file.close()
    print("BOSS READONLY REPRO: %d passed, %d failed" % [passed, failed])
    print(JSON.stringify(cases))
    quit(1 if failed > 0 else 0)

func _check(condition: bool, label: String) -> void:
    checks.append({"label": label, "passed": condition})
    if condition:
        passed += 1
    else:
        failed += 1
        printerr("CONTRACT FAIL: ", label)

func _boss_session(seed_value: int) -> Session:
    var session: Session = Session.new(seed_value)
    session.bot_enabled = false
    session.reset(seed_value)
    var recruited: int = 0
    for offer: Dictionary in (session.teams[0]["shop"] as Array).duplicate(true):
        if offer["kind"] == "hero":
            var reply: Dictionary = session.apply_command(0, "recruit_%d" % recruited, "recruit", {"offer_id": offer["offer_id"]})
            if bool(reply.get("ok", false)):
                recruited += 1
            if recruited == 2:
                break
    session.sim.round_index = 4
    session.sim.reset_round()
    session._open_preparation()
    session.apply_command(0, "ready_boss", "ready")
    return session

func _case_timeout() -> void:
    var session: Session = _boss_session(20261013)
    var before_lives: Array = session.sim.team_lives.duplicate()
    var boss = session.sim.get_unit(999)
    session.sim.tick = 599
    session.sim.elapsed = 29.95
    session.step(0.05)
    var result: Dictionary = session.sim.round_result.duplicate(true)
    var rewards: Array = (session.teams[0] as Dictionary).get("boss_rewards", []).duplicate(true)
    cases.append({"name": "timeout_with_live_boss", "fixture": "Two heroes recruited via public commands, jump disposable fixture to round4 prep and tick599; real Session.step(0.05)", "boss_alive_after": boss.alive, "boss_hp_after": boss.hp, "lives_before": before_lives, "lives_after": session.sim.team_lives.duplicate(), "result": result, "rewards": rewards, "session_phase": session.phase})
    _check(is_equal_approx(float(result.get("elapsed", 0.0)), 30.0), "timeout resolved at30 seconds")
    _check(boss.alive and boss.hp > 0.0, "Boss still alive at timeout")
    _check(int(result.get("winner", -1)) != 0, "live Boss timeout must not count as player victory")
    _check(rewards.is_empty(), "live Boss timeout grants no loot")
    _check(session.sim.team_lives[1] == before_lives[1], "timeout PvE must not consume opponent life")
    _check(session.sim.team_lives[0] == before_lives[0], "timeout PvE preserves player life")

func _case_boss_defeat() -> void:
    var session: Session = _boss_session(20261014)
    session.sim.team_lives[1] = 1
    var before_lives: Array = session.sim.team_lives.duplicate()
    var boss = session.sim.get_unit(999)
    boss.hp = 0.0
    boss.alive = false
    session.step(0.05)
    var result: Dictionary = session.sim.round_result.duplicate(true)
    var rewards: Array = (session.teams[0] as Dictionary).get("boss_rewards", []).duplicate(true)
    cases.append({"name": "boss_defeat_opponent_one_life", "fixture": "Two heroes recruited via public commands, jump disposable fixture to round4 prep; mark Boss defeated and set bot1life; real Session.step(0.05)", "boss_alive_after": boss.alive, "lives_before": before_lives, "lives_after": session.sim.team_lives.duplicate(), "result": result, "rewards": rewards, "match_winner": session.sim.match_winner, "session_phase": session.phase})
    _check(not boss.alive, "Boss defeated in victory fixture")
    _check(int(result.get("winner", -1)) == 0, "Boss defeat counts as PvE victory")
    _check(session.sim.team_lives[1] == before_lives[1], "PvE victory must not consume opponent life")
    _check(session.sim.team_lives[0] >= before_lives[0], "PvE victory does not consume player life")
    _check(rewards.size() == 3, "Boss defeat grants3loot drops")
    _check(session.sim.match_winner == -1 and session.phase == "round_result", "PvE victory must not end match by consuming bot final life")
